func main() {
    if len(frames) == 0 {
        return
    }

    pausa := time.Second / fps

    // Reproducir en bucle hasta pulsar Ctrl+C.
    for {
        for _, frame := range frames {
            fmt.Print("\x1b[H\x1b[2J")
            fmt.Print(frame)
            fmt.Print("\\n")
            time.Sleep(pausa)
        }
    }
}
